      { d: "中", q: "跑步時轉 90 度的角，是哪一種角？", o: ["直角", "銳角", "鈍角", "平角"], a: 0, e: "90 度是直角。", w: ["", "銳角比 90 度小。", "鈍角比 90 度大。", "平角是 180 度。"] }
